<script setup lang="ts">
import { showConfirmation, showError, showSuccess } from '@nextcloud/dialogs'
import { t } from '@nextcloud/l10n'
import { computed, ref, watch } from 'vue'
import NcButton from '@nextcloud/vue/components/NcButton'
import NcSettingsSelectGroup from '@nextcloud/vue/components/NcSettingsSelectGroup'
import HintPopover from '../../components/HintPopover.vue'
import { clearHistory, saveCommonSettings } from '../../services/SettingsService.ts'
import { useAutosave } from './useAutosave.ts'

const props = defineProps<{
	formats: Record<string, Record<string, unknown>>
	restrictExternalStorage: boolean
	sameTab: boolean
	enableSharing: boolean
	preview: boolean
	advanced: boolean
	cronChecker: boolean
	emailNotifications: boolean
	versionHistory: boolean
	limitGroups: string[]
	chat: boolean
	compactHeader: boolean
	feedback: boolean
	forcesave: boolean
	liveViewOnShare: boolean
	help: boolean
	reviewDisplay: string
	theme: string
	unknownAuthor: string
}>()

// Build defFormats and editFormats from the formats object
const defFormats = ref<Record<string, boolean>>(Object.fromEntries(Object.entries(props.formats)
	.filter(([, fmt]) => fmt.mime !== undefined && fmt.mime !== null)
	.map(([name, fmt]) => [name, !!(fmt.def)])))
const editFormats = ref<Record<string, boolean>>(Object.fromEntries(Object.entries(props.formats)
	.filter(([, fmt]) => fmt.editable)
	.map(([name, fmt]) => [name, !!(fmt.edit)])))

// Computed filtered views of formats
const previewFormats = computed(() => Object.entries(props.formats).filter(([, fmt]) => fmt.mime !== undefined && fmt.mime !== null))
const editableFormats = computed(() => Object.entries(props.formats).filter(([, fmt]) => fmt.editable))

const restrictExternalStorage = ref(props.restrictExternalStorage)
const sameTab = ref(props.sameTab)
const enableSharing = ref(props.enableSharing)
const preview = ref(props.preview)
const advanced = ref(props.advanced)
const cronChecker = ref(props.cronChecker)
const emailNotifications = ref(props.emailNotifications)
const versionHistory = ref(props.versionHistory)
const limitGroups = ref<string[]>([...props.limitGroups])
const useGroups = ref(props.limitGroups.length > 0)
const chat = ref(props.chat)
const compactHeader = ref(props.compactHeader)
const feedback = ref(props.feedback)
const forcesave = ref(props.forcesave)
const liveViewOnShare = ref(props.liveViewOnShare)
const help = ref(props.help)
const reviewDisplay = ref(props.reviewDisplay)
const theme = ref(props.theme)
const unknownAuthor = ref(props.unknownAuthor ?? '')
const appliedUnknownAuthor = ref(props.unknownAuthor ?? '')
const unknownAuthorDirty = computed(() => unknownAuthor.value !== appliedUnknownAuthor.value)
const clearing = ref(false)

watch(sameTab, (val) => {
	if (val) {
		enableSharing.value = false
	}
})

watch(useGroups, (val) => {
	if (!val) {
		limitGroups.value = []
	}
})

/**
 * Prompts the user for confirmation, then clears all document co-editing history.
 */
async function onClearHistory() {
	const confirmed = await showConfirmation({
		name: t('onlyoffice', 'Confirm metadata removal'),
		text: t('onlyoffice', 'Are you sure you want to clear metadata?'),
		labelReject: t('core', 'Cancel'),
		severity: 'info',
	})
	if (!confirmed) {
		return
	}

	clearing.value = true
	try {
		await clearHistory()
		showSuccess(t('onlyoffice', 'All history successfully deleted'))
	} catch {
		showError(t('onlyoffice', 'Error'))
	} finally {
		clearing.value = false
	}
}

/**
 * Builds the common settings payload from the current form state.
 */
function buildPayload() {
	return {
		defFormats: defFormats.value,
		editFormats: editFormats.value,
		restrictExternalStorage: restrictExternalStorage.value,
		sameTab: sameTab.value,
		enableSharing: enableSharing.value,
		preview: preview.value,
		advanced: advanced.value,
		cronChecker: cronChecker.value,
		emailNotifications: emailNotifications.value,
		versionHistory: versionHistory.value,
		limitGroups: useGroups.value ? limitGroups.value : [],
		chat: chat.value,
		compactHeader: compactHeader.value,
		feedback: feedback.value,
		forcesave: forcesave.value,
		liveViewOnShare: liveViewOnShare.value,
		help: help.value,
		reviewDisplay: reviewDisplay.value,
		theme: theme.value,
		unknownAuthor: appliedUnknownAuthor.value.trim(),
	}
}

const { flush } = useAutosave({
	build: buildPayload,
	save: saveCommonSettings,
	errorMessage: t('onlyoffice', 'Failed to save common settings'),
})

/**
 * Commits the edited author name and saves it immediately.
 */
function applyUnknownAuthor() {
	appliedUnknownAuthor.value = unknownAuthor.value
	flush()
}
</script>

<template>
	<div class="section section-onlyoffice section-onlyoffice-common">
		<!-- Group access restriction -->
		<p>
			<input
				id="onlyoffice-groups"
				v-model="useGroups"
				type="checkbox"
				class="checkbox">
			<label for="onlyoffice-groups">{{ t('onlyoffice', 'Allow the following groups to access the editors') }}</label>
		</p>
		<p v-if="useGroups" class="block-inline">
			<NcSettingsSelectGroup
				v-model="limitGroups"
				:label="t('core', 'Groups')" />
			<span>{{ t('onlyoffice', 'The user who creates a public link sets its access permissions') }}</span>
		</p>

		<!-- Behaviour -->
		<p>
			<input
				id="onlyoffice-restrict-external-storage"
				v-model="restrictExternalStorage"
				type="checkbox"
				class="checkbox">
			<label for="onlyoffice-restrict-external-storage">{{ t('onlyoffice', 'Restrict access to ONLYOFFICE for files from external storages') }}</label>
		</p>

		<p>
			<input
				id="onlyoffice-preview"
				v-model="preview"
				type="checkbox"
				class="checkbox">
			<label for="onlyoffice-preview">{{ t('onlyoffice', 'Use ONLYOFFICE to generate a document preview (it will take up disk space)') }}</label>
		</p>

		<p>
			<input
				id="onlyoffice-same-tab"
				v-model="sameTab"
				type="checkbox"
				class="checkbox">
			<label for="onlyoffice-same-tab">{{ t('onlyoffice', 'Open file in the same tab') }}</label>
		</p>

		<div v-show="!sameTab" id="onlyoffice-enable-sharing-block">
			<p>
				<input
					id="onlyoffice-enable-sharing"
					v-model="enableSharing"
					type="checkbox"
					class="checkbox">
				<label for="onlyoffice-enable-sharing">{{ t('onlyoffice', 'Enable sharing (might increase editors loading time)') }}</label>
			</p>
		</div>

		<p>
			<input
				id="onlyoffice-advanced"
				v-model="advanced"
				type="checkbox"
				class="checkbox">
			<label for="onlyoffice-advanced">{{ t('onlyoffice', 'Provide advanced document permissions using ONLYOFFICE Docs') }}</label>
		</p>

		<p class="onlyoffice-version-history">
			<span>
				<input
					id="onlyoffice-version-history"
					v-model="versionHistory"
					type="checkbox"
					class="checkbox">
				<label for="onlyoffice-version-history">{{ t('onlyoffice', 'Keep metadata for each version once the document is edited (it will take up disk space)') }}</label>
			</span>
			<NcButton :disabled="clearing" @click="onClearHistory">
				{{ t('onlyoffice', 'Clear') }}
			</NcButton>
		</p>

		<p>
			<input
				id="onlyoffice-cron-checker"
				v-model="cronChecker"
				type="checkbox"
				class="checkbox">
			<label for="onlyoffice-cron-checker">{{ t('onlyoffice', 'Enable background connection check to the editors') }}</label>
		</p>

		<p>
			<input
				id="onlyoffice-email-notifications"
				v-model="emailNotifications"
				type="checkbox"
				class="checkbox">
			<label for="onlyoffice-email-notifications">{{ t('onlyoffice', 'Enable e-mail notifications') }}</label>
		</p>

		<p>{{ t('onlyoffice', 'Unknown author display name') }}</p>
		<p class="onlyoffice-unknown-author">
			<input
				id="onlyoffice-unknown-author"
				v-model="unknownAuthor"
				type="text"
				placeholder=""
				@keyup.enter="applyUnknownAuthor">
			<NcButton :disabled="!unknownAuthorDirty" @click="applyUnknownAuthor">
				{{ t('onlyoffice', 'Apply') }}
			</NcButton>
		</p>

		<!-- Default formats -->
		<p>{{ t('onlyoffice', 'The default application for opening the format') }}</p>
		<div class="onlyoffice-exts">
			<div v-for="[name] in previewFormats" :key="'def-' + name">
				<input
					:id="'onlyoffice-def-format' + name"
					v-model="defFormats[name]"
					type="checkbox"
					class="checkbox">
				<label :for="'onlyoffice-def-format' + name">{{ name }}</label>
			</div>
		</div>

		<!-- Editable formats -->
		<p>{{ t('onlyoffice', 'Open the file for editing (due to format restrictions, the data might be lost when saving to the formats from the list below)') }}</p>
		<div class="onlyoffice-exts">
			<div v-for="[name] in editableFormats" :key="'edit-' + name">
				<input
					:id="'onlyoffice-edit-format' + name"
					v-model="editFormats[name]"
					type="checkbox"
					class="checkbox">
				<label :for="'onlyoffice-edit-format' + name">{{ name }}</label>
			</div>
		</div>

		<br>

		<!-- Editor customization -->
		<h2>{{ t('onlyoffice', 'Editor customization settings') }}</h2>

		<p>
			<input
				id="onlyoffice-forcesave"
				v-model="forcesave"
				type="checkbox"
				class="checkbox">
			<label for="onlyoffice-forcesave">{{ t('onlyoffice', 'Keep intermediate versions when editing (forcesave)') }}</label>
		</p>

		<p>
			<input
				id="onlyoffice-live-view-on-share"
				v-model="liveViewOnShare"
				type="checkbox"
				class="checkbox">
			<label for="onlyoffice-live-view-on-share">{{ t('onlyoffice', 'Enable live-viewing mode when accessing file by public link') }}</label>
		</p>

		<p>
			{{ t('onlyoffice', 'The customization section allows personalizing the editor interface') }}
		</p>

		<p>
			<input
				id="onlyoffice-chat"
				v-model="chat"
				type="checkbox"
				class="checkbox">
			<label for="onlyoffice-chat">{{ t('onlyoffice', 'Display Chat menu button') }}</label>
		</p>

		<p>
			<input
				id="onlyoffice-compact-header"
				v-model="compactHeader"
				type="checkbox"
				class="checkbox">
			<label for="onlyoffice-compact-header">{{ t('onlyoffice', 'Display the header more compact') }}</label>
		</p>

		<p>
			<input
				id="onlyoffice-feedback"
				v-model="feedback"
				type="checkbox"
				class="checkbox">
			<label for="onlyoffice-feedback">{{ t('onlyoffice', 'Display Feedback & Support menu button') }}</label>
		</p>

		<p>
			<input
				id="onlyoffice-help"
				v-model="help"
				type="checkbox"
				class="checkbox">
			<label for="onlyoffice-help">{{ t('onlyoffice', 'Display Help menu button') }}</label>
		</p>

		<!-- Review display mode -->
		<p class="onlyoffice-review-header">
			<span>{{ t('onlyoffice', 'REVIEW mode for viewing') }}</span>
			<HintPopover :label="t('onlyoffice', 'Review mode explanation')">
				<ul>
					<li><strong>{{ t('onlyoffice', 'Markup and balloons') }}</strong> — {{ t('onlyoffice', 'All changes (Editing)') }}</li>
					<li><strong>{{ t('onlyoffice', 'Only markup') }}</strong> — {{ t('onlyoffice', 'All changes (Editing), no balloons') }}</li>
					<li><strong>{{ t('onlyoffice', 'Final') }}</strong> — {{ t('onlyoffice', 'All changes accepted (Preview)') }}</li>
					<li><strong>{{ t('onlyoffice', 'Original') }}</strong> — {{ t('onlyoffice', 'All changes rejected (Preview)') }}</li>
				</ul>
			</HintPopover>
		</p>
		<div class="onlyoffice-tables">
			<div>
				<input
					id="onlyoffice-review-display-markup"
					v-model="reviewDisplay"
					type="radio"
					class="radio"
					value="markup"
					name="reviewDisplay">
				<label for="onlyoffice-review-display-markup">{{ t('onlyoffice', 'Markup and balloons') }}</label>
			</div>
			<div>
				<input
					id="onlyoffice-review-display-simple"
					v-model="reviewDisplay"
					type="radio"
					class="radio"
					value="simple"
					name="reviewDisplay">
				<label for="onlyoffice-review-display-simple">{{ t('onlyoffice', 'Only markup') }}</label>
			</div>
			<div>
				<input
					id="onlyoffice-review-display-final"
					v-model="reviewDisplay"
					type="radio"
					class="radio"
					value="final"
					name="reviewDisplay">
				<label for="onlyoffice-review-display-final">{{ t('onlyoffice', 'Final') }}</label>
			</div>
			<div>
				<input
					id="onlyoffice-review-display-original"
					v-model="reviewDisplay"
					type="radio"
					class="radio"
					value="original"
					name="reviewDisplay">
				<label for="onlyoffice-review-display-original">{{ t('onlyoffice', 'Original') }}</label>
			</div>
		</div>

		<!-- Theme -->
		<p>
			{{ t('onlyoffice', 'Default editor theme') }}
		</p>
		<div class="onlyoffice-tables">
			<div>
				<input
					id="onlyoffice-theme-theme-system"
					v-model="theme"
					type="radio"
					class="radio"
					value="theme-system"
					name="theme">
				<label for="onlyoffice-theme-theme-system">{{ t('onlyoffice', 'Same as system') }}</label>
			</div>
			<div>
				<input
					id="onlyoffice-theme-default-light"
					v-model="theme"
					type="radio"
					class="radio"
					value="default-light"
					name="theme">
				<label for="onlyoffice-theme-default-light">{{ t('onlyoffice', 'Light') }}</label>
			</div>
			<div>
				<input
					id="onlyoffice-theme-default-dark"
					v-model="theme"
					type="radio"
					class="radio"
					value="default-dark"
					name="theme">
				<label for="onlyoffice-theme-default-dark">{{ t('onlyoffice', 'Dark') }}</label>
			</div>
		</div>
	</div>
</template>

<style scoped>
.onlyoffice-unknown-author {
	display: flex;
	align-items: center;
	gap: 8px;
}

.onlyoffice-review-header {
	display: flex;
	align-items: center;
}

#onlyoffice-enable-sharing-block {
    margin-inline-start: 1.5em;
}

.onlyoffice-version-history {
	display: flex;
	align-items: center;
	gap: 8px;
	flex-wrap: wrap;
}

.onlyoffice-exts {
    column-width: 100px;
    -moz-column-width: 100px;
    -webkit-column-width: 100px;
    margin-bottom: 1em;
}

</style>
